<template>
  <div class="held-picker-backdrop" @mousedown.stop @click.self="close" @keydown.esc.stop.prevent="close" @keydown.tab="trapFocus">
    <section ref="panel" class="held-picker" role="dialog" aria-modal="true" aria-labelledby="held-picker-title" :aria-busy="busy">
      <header><div><small>OBJET TENU</small><h2 id="held-picker-title">Équiper {{ pokemon.name }}</h2></div><button ref="close" data-gamepad-back aria-label="Fermer les objets tenus" :disabled="busy" @click="close">×</button></header>
      <div v-if="pokemon.heldItem" class="held-current"><span>Actuellement : <strong>{{ itemName(pokemon.heldItem) }}</strong></span><button data-held-remove :disabled="busy" @click="$emit('equip',null)">Retirer</button></div>
      <label class="held-search">Chercher dans le sac<input v-model="query" type="search" placeholder="Nom ou effet…" :disabled="busy" /></label>
      <nav class="held-filters" aria-label="Catégories d’objets"><button v-for="filter in filters" :key="filter.key" :aria-pressed="category===filter.key" :disabled="busy" @click="category=filter.key">{{ filter.label }}</button></nav>
      <div class="held-list">
        <button v-for="item in filtered" :key="item.key" :data-held-choice="item.key" :aria-pressed="selected===item.key" :disabled="busy || item.key===pokemon.heldItem" @click="selected=item.key"><bag-item-icon :pocket="item.key.endsWith('_berry')?'berries':'held'" :item-key="item.key"/><span><strong>{{ item.name }}</strong><small>{{ description(item) }}</small></span><span class="held-quantity">×{{ item.quantity }}</span></button>
        <p v-if="!filtered.length" class="held-empty">{{ items.length?'Aucun objet ne correspond à ta recherche.':'Ton sac ne contient pas d’objet à faire tenir.' }}</p>
      </div>
      <footer><p v-if="error" class="held-error" role="alert">{{ error }}</p><p v-if="selected && pokemon.heldItem" class="held-help">L’objet actuellement tenu sera rendu à ton sac.</p><button class="held-confirm" data-held-confirm :disabled="busy || !availableSelection" @click="$emit('equip',selected)">{{ busy?'Attribution…':availableSelection?`Donner ${availableSelection.name}`:'Choisis un objet' }}</button></footer>
    </section>
  </div>
</template>
<script>
import BagItemIcon from './BagItemIcon.vue';
import definitions from '@/data/heldItems.json';
const fold=s=>String(s||'').normalize('NFD').replace(/[\u0300-\u036f]/g,'').toLowerCase();
export default {
  components:{BagItemIcon},props:{pokemon:{type:Object,required:true},items:{type:Array,default:()=>[]},busy:Boolean,error:String},
  data:()=>({query:'',category:'all',selected:null,previousFocus:null,filters:[{key:'all',label:'Tous'},{key:'strategy',label:'Stratégie'},{key:'berries',label:'Baies'}]}),
  computed:{availableSelection(){return this.items.find(i=>i.key===this.selected&&i.quantity>0&&i.key!==this.pokemon.heldItem);},filtered(){return this.items.filter(i=>i.quantity>0&&(this.category==='all'||i.key.endsWith('_berry')===(this.category==='berries'))&&fold(i.name+' '+this.description(i)).includes(fold(this.query))).sort((a,b)=>a.name.localeCompare(b.name,'fr'));}},
  mounted(){this.previousFocus=document.activeElement;this.$refs.close.focus({preventScroll:true});},beforeDestroy(){const previous=this.previousFocus;this.$nextTick(()=>{if(previous?.isConnected)previous.focus({preventScroll:true});});},
  methods:{description(i){return i.description||definitions[i.key]?.description||'';},itemName(key){return definitions[key]?.name||key;},close(){if(!this.busy)this.$emit('close');},trapFocus(e){const nodes=[...this.$refs.panel.querySelectorAll('button:not(:disabled),input:not(:disabled)')],first=nodes[0],last=nodes.at(-1);if(e.shiftKey&&document.activeElement===first){e.preventDefault();last.focus();}else if(!e.shiftKey&&document.activeElement===last){e.preventDefault();first.focus();}}}
};
</script>
<style scoped>
