text-align:left;gap:10px;padding:12px}.held-list>button[aria-pressed=true]{border-color:var(--journal-accent);background:var(--journal-selected)}.held-list .bag-object-icon{width:30px;height:30px;flex:none}.held-list>button>span:not(.held-quantity){flex:1;min-width:0}.held-list strong{display:block;font-size:13px}.held-list small{display:block;color:var(--journal-muted);font-size:11px;line-height:1.5;margin-top:3px}.held-quantity{font-size:11px;flex:none;color:var(--journal-muted)}.held-empty{color:var(--journal-muted);margin:10px 0}footer{flex:none;padding:12px 18px;border-top:1px solid var(--journal-border);background:var(--journal-card)}.held-confirm{width:100%;background:var(--journal-accent);color:var(--journal-on-accent);font-weight:600}.held-error{color:var(--journal-danger);margin:0 0 8px}.held-help{font-size:11px;color:var(--journal-muted);margin:0 0 8px}@media(max-width:380px){header{padding:12px}h2{font-size:21px}.held-current{font-size:11px}.held-list{padding:4px 12px 12px}.held-list>button{padding:10px;gap:7px}}
@media(max-height:520px) and (min-width:600px){header{padding:8px 16px}h2{font-size:20px}.held-current{padding:4px 16px}.held-search{padding:6px 16px;display:flex;align-items:center;gap:12px;white-space:nowrap}.held-search input{flex:1;min-width:0}.held-filters{padding:0 16px 8px}footer{padding:8px 16px}}
</style>
